import os
import sys
from taf.hw.internal.device import Device
from taf.hw.channel_emulator import ChannelEmulator
from taf.hw.vertex.executor.ssh_connection import SshConnection
from taf.hw.vertex.exception import OperationNotSupported


class Vertex(Device, ChannelEmulator):
    """
    A hardware device class, provides basic methods to operate hardware.
    """
    _vendor = 'spirent'
    _model = None
    _version = None
    _CONFIGURATION_FILES_DIR = r'C:/configuration_files_for_vertex/'

    def __init__(self, host=None, port=None, proxy=None, proxy_username=None, proxy_password=None, **kwargs):
        super(Vertex, self).__init__()
        self._host = host or "127.0.0.1"
        self._port = port or 3000
        self._proxy = proxy or "127.0.0.1"
        self._proxy_username = proxy_username or 'ute'
        self._proxy_password = proxy_password or 'ute'
        self._connection = SshConnection(self._host, self._port, self._proxy,
                                         self._proxy_username, self._proxy_password, **kwargs)
        self.add_prerequisite(self._connection)
        self._file_path_list = []

    def _setup(self):
        """
        Setup the ssh and socket connection.

        :return:
        """
        self._connection.create_dir(self._CONFIGURATION_FILES_DIR)

    def _teardown(self):
        """
        Teardown ssh and socket connection.
        """
        for file_path in self._file_path_list:
            self._connection.remove_file(file_path)

    def execute_command(self, command):
        """
        Execute vertex RPI command.

        :param command: str, RPI command
        :return: response of RPI command
        """
        return self._connection.execute_command(command)

    def upload_file(self, local_path):
        """
        Upload file from local to vertex host.
        using default remote path 'C:\\configuration_files_for_vertex'

        :param local_path: str, local file path
        :return: remote path
        ,
        """
        remote_file_path = self._CONFIGURATION_FILES_DIR + os.path.basename(local_path)
        self._file_path_list.append(remote_file_path)
        sde_file_path = self._connection.upload_file(local_path, remote_file_path)
        return sde_file_path.replace('/', '\\')

    def load_local_system_setting_file(self, path):
        """
        Load a system-setting file from local pc.

        :param path: str, sde file path
        :return: str, RPI command response
        """
        if self._connection.check_if_vertex_host():
            sde_path = self.upload_file(path)
            command = 'SYSTEM:FILE:LOAD "{}"'.format(sde_path)
            return self.execute_command(command)

        msg = "Precondition of {}:\n".format(sys._getframe().f_code.co_name)
        msg += "Vertex host must act as proxy and provide OpenSSH service."
        raise OperationNotSupported(msg)

    def load_remote_system_setting_file(self, path):
        """
        Load a system-setting file from vertex host.

        :param path: str, sde file path
        :return: str, RPI command response
        """
        command = 'SYSTEM:FILE:LOAD "{}"'.format(path)
        return self.execute_command(command)

    def query_fading_doppler_frequency(self, channel, path):
        """
        Query the Spike Velocity (component due to Moving Vehicle) used when
        Fading Spectrum Shape is set to Bell-Spike (802.11).

        :param channel: int, start form 1, channel NO
        :param path: int[1 to 24], path
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:DFRequency?".format(channel, path)
        return self.execute_command(command)

    def set_fading_doppler_frequency(self, channel, path, frequency):
        """
        Set the Spike Velocity (component due to Moving Vehicle) used when
        Fading Spectrum Shape is set to Bell-Spike (802.11).

        :param channel: int, start form 1, channel NO
        :param path: int[1 to 24], path
        :param frequency: float [-2000 to -0.1, 0.1 to 2000], doppler frequency
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:DFRequency {}".format(channel, path, frequency)
        return self.execute_command(command)

    def query_input_power_level(self, port):
        """
        Query expected input power level.

        :param port: str, "A1" to "A4" and "B1" to "B4" can be passed in
        :return: str, RPI command response
        """
        command = "SYSTEM:PORT:{}:INPut?".format(port)
        return self.execute_command(command)

    def set_input_power_level(self, port, dbm_value):
        """
        Set input power level.

        :param port: str, "A1" to "A4" and "B1" to "B4" can be passed in
        :param dbm_value: int, -50 to 15
        :return: str, RPI command response
        """
        command = "SYSTEM:PORT:{}:INPut {}".format(port, dbm_value)
        return self.execute_command(command)

    def query_output_power_level(self, port):
        """
        Query expected output power level.

        :param port: str, "A1" to "A4" and "B1" to "B4" can be passed in
        :return: str, RPI command response
        """
        command = "SYSTEM:PORT:{}:OUTPut?".format(port)
        return self.execute_command(command)

    def set_output_power_level(self, port, dbm_value):
        """
        Set output power level.

        :param port: str, "A1" to "A4" and "B1" to "B4" can be passed in
        :param dbm_value: int, -110 to -20
        :return: str, RPI command response
        """
        command = "SYSTEM:PORT:{}:OUTPut {}".format(port, dbm_value)
        return self.execute_command(command)

    def set_noise_level(self, port, dbm_value):
        """
        Set the Noise Level for the specified port.

        :param port: str, "A1" to "A4" and "B1" to "B4" can be passed in
        :param dbm_value: int, -50 to 15
        :return: str, RPI command response
        """
        command = "SYSTEM:PORT:{}:INTerferer:NOISElevel {}".format(port, dbm_value)
        return self.execute_command(command)

    def load_local_iq_playback_file(self, path):
        """
        Load the IQPlayback file and transfer it to the channel emulator.

        :param path: str, IQPlayback file path
        :return: str, RPI command response
        """
        if self._connection.check_if_vertex_host():
            txt_path = self.upload_file(path)
            command = 'SYSTEM:IQP:COMPile:FILE "{}"'.format(txt_path)
            return self.execute_command(command)

        msg = "Precondition of {}:\n".format(sys._getframe().f_code.co_name)
        msg += "Vertex host must act as proxy and provide OpenSSH service."
        raise OperationNotSupported(msg)

    def load_remote_iq_playback_file(self, path):
        """
        Load the IQPlayback file on remote pc.

        :param path: IQPlayback file path
        :return: str, RPI command response
        """
        command = 'SYSTEM:IQP:COMPile:FILE "{}"'.format(path)
        return self.execute_command(command)

    def query_iq_playback_status(self):
        """
        Query IQ Playback status.

        :return: str, RPI command response
        """
        command = "SYSTEM:IQP?"
        return self.execute_command(command)

    def enable_iq_playback(self):
        """
        Enable IQ Playback, set the IQ Playback ON.

        :return: str, RPI command response
        """
        command = "SYSTEM:IQP ON"
        return self.execute_command(command)

    def disable_iq_playback(self):
        """
        Disable IQ Playback, set the IQ Playback OFF.

        :return: str, RPI command response
        """
        command = "SYSTEM:IQP OFF"
        return self.execute_command(command)

    def start_channel_emulation(self):
        """
        Start playing channel emulation.

        :return: str, RPI command response
        """
        command = "SYSTEM:EMULATION:PLAY"
        return self.execute_command(command)

    def pause_channel_emulation(self):
        """
        Pause playing channel emulation.

        :return: str, RPI command response
        """
        command = "SYSTEM:EMULATION:PAUSE"
        return self.execute_command(command)

    def stop_channel_emulation(self):
        """
        Stop playing channel emulation.

        :return: str, RPI command response
        """
        command = "SYSTEM:EMULATION:STOP"
        return self.execute_command(command)

    def query_high_speed_train_ds(self, channel, path):
        """
        Query High Speed Train Ds(m) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:FSHift:HST:INIDs?".format(channel, path)
        return self.execute_command(command)

    def set_high_speed_train_ds(self, channel, path, ds):
        """
        Set High Speed Train Ds(m) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :param ds: float, high speed train ds
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:FSHift:HST:INIDs {}".format(channel, path, ds)
        return self.execute_command(command)

    def query_high_speed_train_dmin(self, channel, path):
        """
        Query High Speed Train Dmin(m) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:FSHift:HST:DMIN?".format(channel, path)
        return self.execute_command(command)

    def set_high_speed_train_dmin(self, channel, path, dmin):
        """
        Set High Speed Train Dmin(m) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :param dmin: float, high speed train dmin
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:FSHift:HST:DMIN {}".format(channel, path, dmin)
        return self.execute_command(command)

    def query_high_speed_train_velocity(self, channel, path):
        """
        Query High Speed Train Velocity(km/h) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:FSHift:HST:VELocity?".format(channel, path)
        return self.execute_command(command)

    def set_high_speed_train_velocity(self, channel, path, velocity):
        """
        Set High Speed Train Velocity(km/h) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :param velocity: float, high speed train velocity
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:FSHift:HST:VELocity {}".format(channel, path, velocity)
        return self.execute_command(command)

    def query_high_speed_train_fd(self, channel, path):
        """
        Query High Speed Train fd(Hz)i.e. maximum Doppler for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:FSHift:HST:MAXDoppler?".format(channel, path)
        return self.execute_command(command)

    def set_high_speed_train_fd(self, channel, path, fd):
        """
        Set High Speed Train fd(Hz)i.e. maximum Doppler for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :param fd: float, high speed train fd
        :return: str, RPI command response
        """
        command = "SYSTEM:CHM{}:PROP:PATH{}:FSHift:HST:MAXDoppler {}".format(channel, path, fd)
        return self.execute_command(command)
